 fn submitted_progress(&self)->RetainedCloneProgress{self.submitted}fn grant_for(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,semio_framework_value::ValueError>{assert!(semio_framework_value::retained_clone::retained_clone_grant_admits(self.grant,d));self.issued=true;Ok(self.grant)}
 fn accept_for(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),semio_framework_value::ValueError>{self.submitted=self.submitted.checked_add(p)?;assert!(p.fits(g));Ok(())}
